def execute(filters=None):
    try:
        columns = get_columns()
        data = get_data(filters)
        return columns, data
    except Exception as e:
        frappe.log_error(f"Report execution failed: {str(e)}", "RFQ Report Error")
        frappe.msgprint(f"Error executing report: {str(e)}")
        return get_columns(), []


def get_columns():
    return [
        {"label": _("Material Request"), "fieldname": "material_request", "fieldtype": "Link", "options": "Material Request", "width": 150},
        {"label": _("Transaction Date"), "fieldname": "transaction_date", "fieldtype": "Date", "width": 110},
        {"label": _("Item Code"), "fieldname": "item_code", "fieldtype": "Link", "options": "Item", "width": 150},
        {"label": _("Item Name"), "fieldname": "item_name", "fieldtype": "Data", "width": 150},
        {"label": _("Quantity"), "fieldname": "qty", "fieldtype": "Float", "width": 100},
        {"label": _("UOM"), "fieldname": "uom", "fieldtype": "Link", "options": "UOM", "width": 80},
        {"label": _("Purchase UOM"), "fieldname": "purchase_uom", "fieldtype": "Link", "options": "UOM", "width": 110},
        {"label": _("Conversion Factor"), "fieldname": "conversion_factor", "fieldtype": "Float", "width": 120},
        {"label": _("Qty in Purchase UOM"), "fieldname": "qty_in_purchase_uom", "fieldtype": "Float", "width": 140},
        {"label": _("Required Date"), "fieldname": "schedule_date", "fieldtype": "Date", "width": 110},
        {"label": _("Target Warehouse"), "fieldname": "warehouse", "fieldtype": "Link", "options": "Warehouse", "width": 150},
        {"label": _("Approval Status"), "fieldname": "workflow_state", "fieldtype": "Data", "width": 120},
        {"label": _("Rate"), "fieldname": "rate", "fieldtype": "Currency", "width": 100},
        {"label": _("Amount"), "fieldname": "amount", "fieldtype": "Currency", "width": 120}
    ]


def get_data(filters):
    if not filters or not filters.get("from_date") or not filters.get("to_date"):
        frappe.throw(_("From Date and To Date are mandatory"))

    try:
        data = frappe.db.sql("""
            SELECT
                mr.name AS material_request,
                mr.transaction_date,
                mri.item_code,
                mri.item_name,
                mri.qty,
                mri.uom,
                mri.schedule_date,
                mri.warehouse,
                mr.workflow_state,
                mri.rate,
                mri.amount,
                mri.name as mr_item_name
            FROM
                `tabMaterial Request` mr
            JOIN
                `tabMaterial Request Item` mri ON mri.parent = mr.name
            WHERE
                mr.docstatus < 2 
                AND mri.custom_purchase = 1 
                AND mr.transaction_date BETWEEN %(from_date)s AND %(to_date)s
            ORDER BY
                mr.transaction_date DESC, mr.name DESC
        """, filters, as_dict=1)
    except Exception as e:
        frappe.log_error(f"SQL query failed: {str(e)}", "RFQ Report SQL Error")
        frappe.throw(_("Failed to fetch data: {0}").format(str(e)))

    if not data:
        return []

    for row in data:
        try:
            process_row(row)
        except Exception as e:
            frappe.log_error(f"Error processing item {row.get('item_code', 'Unknown')}: {str(e)}", "RFQ Report Row Processing Error")
            row['purchase_uom'] = row.get('uom', 'Nos')
            row['conversion_factor'] = 1.0
            row['qty_in_purchase_uom'] = row.get('qty', 0)

    return data


def process_row(row):
    try:
        item = frappe.get_cached_doc("Item", row['item_code'])
    except Exception as e:
        frappe.log_error(f"Failed to fetch item {row['item_code']}: {str(e)}", "RFQ Report Item Fetch Error")
        row['purchase_uom'] = row.get('uom', 'Nos')
        row['conversion_factor'] = 1.0
        row['qty_in_purchase_uom'] = row.get('qty', 0)
        return

    purchase_uom = None
    try:
        purchase_uom = getattr(item, 'purchase_uom', None)
    except:
        pass

    if not purchase_uom:
        try:
            purchase_uom = item.stock_uom
        except:
            purchase_uom = row.get('uom', 'Nos')

    row['purchase_uom'] = purchase_uom

    conversion_factor = 1.0
    if row['uom'] != purchase_uom:
        try:
            conversion_factor = get_uom_conversion_factor(row['item_code'], row['uom'], purchase_uom)
        except Exception as e:
            frappe.log_error(f"Conversion factor error for {row['item_code']}: {str(e)}", "RFQ Report Conversion Error")
            conversion_factor = 1.0

    row['conversion_factor'] = conversion_factor

    try:
        qty = flt(row.get('qty', 0))
        row['qty_in_purchase_uom'] = flt(qty * conversion_factor, 2)
    except:
        row['qty_in_purchase_uom'] = row.get('qty', 0)


def get_uom_conversion_factor(item_code, from_uom, to_uom):
    if from_uom == to_uom:
        return 1.0

    try:
        conversion = frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": to_uom}, "conversion_factor")
        if conversion:
            return flt(conversion)
    except:
        pass

    try:
        reverse = frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": from_uom}, "conversion_factor")
        if reverse and flt(reverse) != 0:
            return flt(1.0 / reverse)
    except:
        pass

    return 1.0
